CREATE TYPE "Role" AS ENUM ('USER','ADMIN');
CREATE TYPE "ListingStatus" AS ENUM ('ACTIVE','PAUSED','DISABLED');
CREATE TYPE "BookingStatus" AS ENUM ('PENDING','ACCEPTED','DECLINED','CANCELLED','COMPLETED');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT UNIQUE NOT NULL,"passwordHash" TEXT NOT NULL,"name" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'USER',"isOwner" BOOLEAN NOT NULL DEFAULT false,"disabled" BOOLEAN NOT NULL DEFAULT false,"avatarUrl" TEXT,"bio" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Listing" ("id" TEXT PRIMARY KEY,"slug" TEXT UNIQUE NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"category" TEXT NOT NULL,"location" TEXT NOT NULL,"pricePerDay" INTEGER NOT NULL,"securityDeposit" INTEGER NOT NULL DEFAULT 0,"features" TEXT[] NOT NULL,"rules" TEXT[] NOT NULL,"deliveryOptions" TEXT[] NOT NULL,"details" JSONB NOT NULL DEFAULT '{}',"status" "ListingStatus" NOT NULL DEFAULT 'ACTIVE',"ownerId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Photo" ("id" TEXT PRIMARY KEY,"url" TEXT NOT NULL,"alt" TEXT,"position" INTEGER NOT NULL DEFAULT 0,"listingId" TEXT NOT NULL REFERENCES "Listing"("id") ON DELETE CASCADE);
CREATE TABLE "Favorite" ("userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"listingId" TEXT NOT NULL REFERENCES "Listing"("id") ON DELETE CASCADE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("userId","listingId"));
CREATE TABLE "Booking" ("id" TEXT PRIMARY KEY,"listingId" TEXT NOT NULL REFERENCES "Listing"("id") ON DELETE CASCADE,"renterId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"startDate" DATE NOT NULL,"endDate" DATE NOT NULL,"totalPrice" INTEGER NOT NULL,"status" "BookingStatus" NOT NULL DEFAULT 'PENDING',"note" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Message" ("id" TEXT PRIMARY KEY,"body" TEXT NOT NULL,"senderId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"recipientId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"bookingId" TEXT REFERENCES "Booking"("id") ON DELETE SET NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Review" ("id" TEXT PRIMARY KEY,"rating" INTEGER NOT NULL,"comment" TEXT NOT NULL,"authorId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"listingId" TEXT NOT NULL REFERENCES "Listing"("id") ON DELETE CASCADE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("authorId","listingId"));
CREATE INDEX "Listing_category_location_status_idx" ON "Listing"("category","location","status"); CREATE INDEX "Booking_listingId_startDate_endDate_status_idx" ON "Booking"("listingId","startDate","endDate","status"); CREATE INDEX "Message_senderId_recipientId_createdAt_idx" ON "Message"("senderId","recipientId","createdAt");
